# Get non-empty, non-comment lines
lines = [line.strip() for line in student_code.split('\n') if line.strip() and not line.strip().startswith('#')]

# Task 1: Check import
if not any('import numpy as np' in line for line in lines):
    raise AssertionError('Task 1: Missing "import numpy as np"')

# Task 2: Check np.array() call
if not any('temp_array' in line and 'np.array' in line for line in lines):
    raise AssertionError('Task 2: temp_array should use np.array()')
if not any('np.array(temperatures)' in line for line in lines):
    raise AssertionError('Task 2: Should pass temperatures list to np.array()')

# Task 3: Check array is printed (flexible format)
if not any('print(temp_array)' in line or ('print' in line and 'temp_array' in line and 'f"' in line) for line in lines):
    raise AssertionError('Task 3: Should print the array')

# Task 4: Check dtype is printed (flexible format)
if not any('temp_array.dtype' in line and 'print' in line for line in lines):
    raise AssertionError('Task 4: Should print dtype using temp_array.dtype')

# Task 5: Check shape is printed (flexible format)
if not any('temp_array.shape' in line and 'print' in line for line in lines):
    raise AssertionError('Task 5: Should print shape using temp_array.shape')

print('TEST_PASSED')
